// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/noise.ts, then fixed by hand where it says so.
// Noise: building, fighting and gunfire carry.
//
// A noise of radius r (Manhattan) at a point wakes the dormant zombies within
// r, draws idle static and herd zombies within r to come and look, and turns
// any herd within HERD_HEARING x r towards it (on through the point and out
// the far side). Nothing is stored: a noise happens and its effects stay.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Noise
{

    /// <summary>How far each kind of noise carries.</summary>
    public static readonly JsRecord<double> NOISE = new() { ["building"] = 10, ["fighting"] = 6, ["gunfire"] = 30, ["generator"] = 12, ["scream"] = 30, ["lure"] = 25, ["glass"] = 15, ["alarm"] = 25, ["helicopter"] = 35, ["engine"] = 18 };

    /// <summary>Herds hear from this many times further than a noise's radius.</summary>
    public const int HERD_HEARING = 2;

    public static void makeNoise(SimState state, Point p, object kind)
    {
        var r = NOISE[Js.Idx(kind)];
        var woke = wakeDormantNear(state, (d) => Space.manhattan(d, p) <= r);
        if (woke > 0)
        {
            Events.logEvent(state, $"The {Js.Str(kind)} at ({Js.Str(p.x)}, {Js.Str(p.y)}) woke {Js.Str(woke == 1 ? "a zombie" : $"{Js.Str(woke)} zombies")}");
        }
        var __d0 = state.grid;
        var width = __d0.width;
        var height = __d0.height;
        foreach (var z in Js.Iter(state.zombies))
        {
            if (z.kind != "static" && z.kind != "herd" || z.targetId != null || Js.T(z.hordeId) || Space.manhattan(z.pos, p) > r)
            {
                continue;
            }
            z.heading = z.kind == "static" ? new() { x = p.x, y = p.y } : new() { x = clamp(2 * p.x - z.pos.x, width), y = clamp(2 * p.y - z.pos.y, height) };
            z.path = [];
        }
        Hordes.hordesHear(state, p, r, (from) => new() { x = clamp(2 * p.x - from.x, width), y = clamp(2 * p.y - from.y, height) });
        foreach (var h in Js.Iter(state.herds))
        {
            if (Space.manhattan(h, p) > r * HERD_HEARING)
            {
                continue;
            }
            var to = new() { x = clamp(2 * p.x - h.x, width), y = clamp(2 * p.y - h.y, height) };
            if (to.x == h.to.x && to.y == h.to.y)
            {
                continue;
            }
            h.to = to;
            Events.logEvent(state, $"A herd of {Js.Str(h.size)} turned towards the {Js.Str(kind)} at ({Js.Str(p.x)}, {Js.Str(p.y)})");
        }
    }

    public static /*TODO return type*/object clamp(double v, double size)
    {
        return JsMath.max(0, JsMath.min(size - 1, v));
    }

    /// <summary>Dormant zombies matching `near` get up as static zombies. Returns how many.</summary>
    public static double wakeDormantNear(SimState state, Func<Point, bool> near)
    {
        var woke = 0;
        foreach (var d in Js.Iter([.. state.dormant]))
        {
            if (!Js.T(near(d)))
            {
                continue;
            }
            if (state.zombies.length >= Zombies.MAX_ZOMBIES)
            {
                break;
            }
            state.dormant.splice(state.dormant.indexOf(d), 1);
            var p = Grids.getTile(state.grid, d.x, d.y) == "floor" ? d : Space.nearestTile(state.grid, d, (x, y) => Grids.getTile(state.grid, x, y) == "floor");
            if (!Js.T(p) || !Js.T(Grids.inBounds(state.grid, p.x, p.y)))
            {
                continue;
            }
            ZombieKinds.giveVariant(Zombies.addZombie(state, p.x, p.y, Zombies.zombieHealthForNight(Time.dayOf(state.tick)), "static"), Time.dayOf(state.tick));
            woke += 1;
        }
        return woke;
    }
}
